(()=>{const packed=JSON.parse(document.getElementById('packed-evidence').textContent),ready=new Map();function unpack(id){if(!ready.has(id))ready.set(id,(async()=>{const binary=atob(packed[id]),bytes=Uint8Array.from(binary,c=>c.charCodeAt(0)),stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));return URL.createObjectURL(new Blob([await new Response(stream).arrayBuffer()],{type:'application/pdf'}));})().catch(error=>{ready.delete(id);throw error;}));return ready.get(id);}Object.keys(packed).forEach(id=>{const links=[...document.querySelectorAll('a[href="#'+id+'"]')];links.forEach(link=>{link.addEventListener('click',async event=>{if(link.getAttribute('href')!=='#'+id)return;event.preventDefault();try{link.href=await unpack(id);link.click();}catch{alert('The PDF could not be opened. Please use a current version of Edge, Chrome, Firefox or Safari.');}});});unpack(id).then(url=>links.forEach(link=>link.href=url)).catch(()=>{});});})();